formulas.program:
input principal: money;
input rate: rational;
input periods: int;
principal * (1 + rate) ^ periods

input amount: money;
input rate: rational;
input periods: int;
amount / (1 + rate) ^ periods

input principal: money;
input rate: rational;
input periods: int;
if rate == 0 then principal / periods else principal * rate / (1 - (1 + rate) ^ (-periods))

input rate: rational;
input cashflows: vector[money];
fold(range(0, len(cashflows)), at(cashflows, 0) * 0, (acc, t) => acc + at(cashflows, t) / (1 + rate) ^ t)

input principal: money;
input rate: rational;
input periods: int;
principal * rate * periods

input net: money;
input rate: rational;
net * (1 + rate)

input old: rational;
input new: rational;
(new - old) / old * 100

input values: vector[rational];
input weights: vector[rational];
dot(values, weights) / sum(weights)

input m: quantity[kg];
input v: quantity[m/s];
m * v ^ 2 / 2

input m1: quantity[kg];
input m2: quantity[kg];
input r: quantity[m];
const("G") * m1 * m2 / r ^ 2

input n: quantity[mol];
input t: quantity[K];
input v: quantity[m^3];
n * const("R") * t / v

input mass: quantity[kg];
input height: quantity[m];
to(mass / height ^ 2, "kg/m^2")

input distance: quantity[km];
input fuel: quantity[L];
to(fuel / distance, "L/km") * 100
